import { convertToGitHubMatrix, getGithubOutputFile, getGithubSamplesGroup, setGithubTaskOutput } from 'generator-jhipster/ci';
import BaseCoreGenerator from 'generator-jhipster/generators/base-core';

/** The GitHub matrix of a samples group, a workflow of the CI: a job by sample of the group, generated by generate-sample. */
export default class extends BaseCoreGenerator {
  /** @type {string} */
  samplesGroup;
  /** @type {object} */
  matrix;

  get [BaseCoreGenerator.WRITING]() {
    return this.asAnyTaskGroup({
      async buildMatrix() {
        // The describe-samples module awaits its descriptions at its top level: imported when used, not with this
        // generator, which yeoman-environment requires.
        const { groups, samplesGroupFolder } = await import('../describe-samples/index.mjs');
        if (!groups.includes(this.samplesGroup)) {
          throw new Error(`Samples group ${this.samplesGroup} not found, expected one of ${groups.join(', ')}`);
        }
        const { samples, warnings } = await getGithubSamplesGroup(samplesGroupFolder, this.samplesGroup);
        if (warnings.length > 0) {
          this.log.info(warnings.join('\n'));
        }
        this.matrix = convertToGitHubMatrix(samples);
        this.log.info('matrix', this.matrix);
        if (getGithubOutputFile()) {
          setGithubTaskOutput('matrix', JSON.stringify(this.matrix));
        }
      },
    });
  }
}
